import 'package:flutter/widgets.dart';

String tr(BuildContext context, String source) =>
    translateForLanguage(Localizations.localeOf(context).languageCode, source);

String translateForLanguage(String languageCode, String source) {
  if (languageCode != 'en') return source;
  return _english[source] ?? source;
}

